 code=[('df = pd.read_csv("fishmarket_practice.csv")','표 불러오기'),('df["Species"].value_counts()','품종별 마리 수'),('df[df["Weight"] <= 0]','무게 0 이하인 이상한 기록 찾기'),('df.groupby("Species")["Weight"].mean()','품종별 평균 무게')],
